// components/pages/Transactions.js
import React, { useState, useEffect } from 'react';
import { apiCall, escapeHtml } from '../../utils/api';

const Transactions = ({ showToast }) => {
  const [tills, setTills] = useState([]);
  const [loading, setLoading] = useState(true);

  const loadData = async () => {
    setLoading(true);
    const result = await apiCall('getTills');
    if (result.success) {
      setTills(result.tills || []);
    }
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleAddUnits = async (rowIndex) => {
    const add = prompt('Enter number of units to ADD:');
    if (add && !isNaN(parseFloat(add)) && parseFloat(add) > 0) {
      const res = await apiCall('updateUnits', { rowIndex, addUnits: parseFloat(add) });
      if (res.success) {
        showToast(`Units updated to ${res.newUnits}`);
        loadData();
      } else {
        showToast('Failed to update units', true);
      }
    }
  };

  if (loading) {
    return (
      <div className="loading">
        <i className="fas fa-spinner fa-pulse"></i> Loading tills...
      </div>
    );
  }

  if (tills.length === 0) {
    return (
      <div className="empty-state">
        <i className="fas fa-inbox"></i>
        <br />No tills available
      </div>
    );
  }

  return (
    <>
      <h3 className="section-title"><i className="fas fa-exchange-alt"></i> Unit Transactions</h3>
      <div className="table-wrapper">
        <table className="modern-table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Till Number</th>
              <th>Store</th>
              <th>Current Units</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {tills.map((till, index) => (
              <tr key={index}>
                <td><strong>{escapeHtml(till.name || '-')}</strong></td>
                <td>{escapeHtml(till.tillNumber || '-')}</td>
                <td>{escapeHtml(till.storeNumber || '-')}</td>
                <td><span className="units-black">{till.units || 0} units</span></td>
                <td>
                  <button 
                    className="action-btn" 
                    onClick={() => handleAddUnits(till.rowIndex)}
                  >
                    Add Units
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </>
  );
};

export default Transactions;
